"""Turn census.json into CENSUS.md (brick x map counts + class families)."""
import json
import os
from collections import defaultdict

HERE = os.path.dirname(__file__)
d = json.load(open(os.path.join(HERE, "census.json")))


def short(f):
    pack = f.split("/")[0]
    name = f.split("/")[-1][:-5]
    return f"{pack} {name}"


bricks = list(next(iter(d.values()))["bricks"])
lines = ["# Census — every brick, every map", "",
         "Generated by `tools/census.py` + `tools/census_md.py` from the live map files on this branch "
         "(dark theme, 1280 px, visible elements only; index maps scoped to `#conceptMap`). "
         "Class-matched bricks use the regexes in `census.py`; box levels, strips, tones and graph paper "
         "use computed style. Counts are elements, not lines.", ""]

lines += ["## 1. Brick counts per map", ""]
hdr = "| map | " + " | ".join(bricks) + " |"
lines += [hdr, "|" + "---|" * (len(bricks) + 1)]
tot = defaultdict(int)
for f, r in d.items():
    row = [str(r["bricks"][b]["count"] or "") for b in bricks]
    for b in bricks:
        tot[b] += r["bricks"][b]["count"]
    lines.append(f"| {short(f)} | " + " | ".join(row) + " |")
lines.append("| **total** | " + " | ".join(f"**{tot[b]}**" for b in bricks) + " |")
lines.append("")

lines += ["## 2. Class families per brick, per pack", "",
          "Each brick's markup, split by pack. More than one family for the same brick inside one "
          "pack, or different families across packs, is what STANDARDISE.md works from.", ""]
for b in bricks:
    fam = defaultdict(lambda: defaultdict(int))
    for f, r in d.items():
        pack = f.split("/")[0]
        for c, n in r["bricks"][b]["classes"].items():
            fam[pack][c] += n
    if not fam:
        continue
    lines.append(f"### {b}")
    lines.append("")
    lines.append("| pack | classes (count) |")
    lines.append("|---|---|")
    for pack in sorted(fam):
        cs = ", ".join(f"`.{c}` {n}" for c, n in sorted(fam[pack].items(), key=lambda x: -x[1]))
        lines.append(f"| {pack} | {cs} |")
    lines.append("")

lines += ["## 3. Computed-style checks per map", "",
          "Box levels = deepest nesting of fully bordered, non-pill boxes inside the map (1 = no box "
          "inside a box). Strip = left border at least 3 px and thicker than the right border. "
          "Tones = bordered boxes whose border colour equals a token.", "",
          "| map | bordered boxes | box levels | thick-left strips | graph paper | stop-red boxes | paragraph refs in text |",
          "|---|---:|---:|---:|---|---:|---:|"]
for f, r in d.items():
    strips = [s for s in r["strips"] if "lc-arrow" not in s["cls"]]
    lines.append(f"| {short(f)} | {r['boxes']} | {r['max_box_depth'] + 1} | {len(strips)} | "
                 f"{'yes' if r['graph_paper'] else ''} | {r['tones'].get('stop', '') or ''} | {len(r['para_text']) or ''} |")
lines.append("")
lines += ["Note: `.lc-arrow` (IAS 16 timeline arrowhead) is drawn with a 6 px left border and is excluded from the strip count.", ""]

lines += ["## 4. Every thick-left strip", "", "| map | classes | first words |", "|---|---|---|"]
for f, r in d.items():
    for s in r["strips"]:
        if "lc-arrow" in s["cls"]:
            continue
        t = s["text"].replace("\n", " ").replace("|", "/")[:45]
        lines.append(f"| {short(f)} | `{s['cls']}` | {t} |")
lines.append("")

lines += ["## 5. Every paragraph reference in map text", "",
          "Regex: `para N`, `IN13`, `BCnn`, `D16(`, `App D`. Chip markup (`.cite`) and plain prose are both listed; "
          "only chip markup is a formatting issue.", "", "| map | element class | text |", "|---|---|---|"]
for f, r in d.items():
    for p in r["para_text"]:
        lines.append(f"| {short(f)} | `{p['cls'] or '(plain text)'}` | {p['text']} |")
lines.append("")

open(os.path.join(HERE, "..", "CENSUS.md"), "w").write("\n".join(lines))
print("ok")
